/* @lc app=leetcode id=3544 lang=kotlin */ class Solution { fun subtreeInversionSum(edges: Array<IntArray>, nums: IntArray, k: Int): Long = nums.size.let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> LongArray(n * (k + 1) * 2).also { dp -> order.forEach { v -> g[v].orEmpty().filter { par[it] == v && it != 0 }.let { ch -> (1..k).forEach { d -> (0..1).forEach { s -> (1 - 2 * s).let { sg -> maxOf(sg.toLong() * nums[v] + ch.sumOf { dp[(it * (k + 1) + minOf(d + 1, k)) * 2 + s] }, if (d >= k) -sg.toLong() * nums[v] + ch.sumOf { dp[(it * (k + 1) + 1) * 2 + 1 - s] } else Long.MIN_VALUE / 2).let { dp[(v * (k + 1) + d) * 2 + s] = it } } } } } } }.let { it[k * 2] } } } } } }